"""One inference path shared by the evaluation script and web API."""
from functools import lru_cache
import json
import os
import numpy as np
from gridpulse.config import ROOT, backend
from gridpulse.schema import features, validate, training_data
from gridpulse.quickml import QuickMLClient


@lru_cache(maxsize=1)
def local_bundle():
    path = ROOT / "models/local_model.joblib"
    if not path.exists():
        raise RuntimeError("Local model is missing. Run python train.py first, then restart the app.")
    import joblib
    # Only load the model generated by this project's train.py; never accept model uploads.
    return joblib.load(path)


@lru_cache(maxsize=1)
def medians():
    path = ROOT / "models/feature_medians.json"
    if path.exists():
        return json.loads(path.read_text(encoding="utf-8"))
    # QuickML can run without a local model; statistics come only from supplied training data.
    return training_data(ROOT / "train_telemetry.csv")[2]


@lru_cache(maxsize=1)
def quickml_client():
    return QuickMLClient()


def forecast(frame, *, hourly_window=False):
    clean, warnings = validate(frame, medians(), hourly_window=hourly_window)
    selected = backend()
    if selected == "quickml":
        mode = os.getenv("QUICKML_FEATURE_MODE", "engineered")
        if mode not in {"engineered", "raw"}:
            raise ValueError("QUICKML_FEATURE_MODE must be engineered or raw.")
        payload = features(clean) if mode == "engineered" else clean
        prediction = np.asarray(quickml_client().predict(payload.to_dict(orient="records")), dtype=float)
    else:
        prediction = np.maximum(0, local_bundle()["model"].predict(features(clean)))
    if prediction.shape != (len(clean),) or not np.isfinite(prediction).all() or (prediction < 0).any():
        raise RuntimeError("The forecast provider returned invalid predictions.")
    return clean, prediction, warnings, selected
